spec.setup_code:
var seed = 12345;
function rnd() { seed |= 0; seed = (seed + 0x6D2B79F5) | 0; var t = Math.imul(seed ^ (seed >>> 15), 1 | seed); t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t; return ((t ^ (t >>> 14)) >>> 0) / 4294967296; }
function gauss() { var u = rnd() + 1e-9, v = rnd(); return Math.sqrt(-2 * Math.log(u)) * Math.cos(6.283185307 * v); }
var N = 300, X = [], Y = [], W = [], D2 = [], SH = [];
for (var i = 0; i < N; i++) {
  var th = Math.PI * rnd();
  if (i < N / 2) { X.push(Math.cos(th) + 0.06 * gauss()); Y.push(Math.sin(th) + 0.06 * gauss()); }
  else { X.push(1 - Math.cos(th) + 0.06 * gauss()); Y.push(0.5 - Math.sin(th) + 0.06 * gauss()); }
  W.push(0); D2.push(0); SH.push(0);
}
var SIG = [1.8, 0.38, 0.07];
var CAP = ['high σ: the best guess is the average of everything', 'medium σ: which crescent?', 'low σ: just clean up the detail'];
var PERIOD = 15, PH = 5, HOLD = 4.2;
function sm(t) { t = Math.max(0, Math.min(1, t)); return t * t * (3 - 2 * t); }

function fit(ctx, s, maxW, size) {
  ctx.font = size + 'px sans-serif';
  while (ctx.measureText(s).width > maxW && size > 11) { size--; ctx.font = size + 'px sans-serif'; }
  return ctx.measureText(s).width;
}
function label(ctx, s, x, y, width, color) {
  ctx.font = '12px sans-serif';
  var w = ctx.measureText(s).width;
  x = Math.max(4, Math.min(width - 4 - w, x));
  ctx.fillStyle = color; ctx.textAlign = 'left';
  ctx.fillText(s, x, y);
}

function draw(ctx, width, height, time, dt) {
  ctx.fillStyle = '#ffffff';
  ctx.fillRect(0, 0, width, height);

  var p = time % PERIOD;
  var k = Math.floor(p / PH), u = p - k * PH;
  var e = u > HOLD ? sm((u - HOLD) / (PH - HOLD)) : 0;
  var k2 = (k + 1) % 3;
  var ls = Math.log(SIG[k]) * (1 - e) + Math.log(SIG[k2]) * e;
  var sig = Math.exp(ls);
  var shown = e > 0.5 ? k2 : k;
  var capA = Math.abs(1 - 2 * e);

  // layout
  var plotTop = 58, plotBot = height - 72;
  var ph = plotBot - plotTop;
  var s = Math.min((width - 24) / 3.6, ph / 2.1);
  var ox = (width - 3.6 * s) / 2 - (-1.3) * s;
  var oy = plotTop + (ph - 2.1 * s) / 2 + 1.3 * s;
  function PX(x) { return ox + x * s; }
  function PY(y) { return oy - y * s; }

  // caption
  ctx.textAlign = 'center';
  ctx.globalAlpha = capA;
  fit(ctx, CAP[shown], width - 20, 14);
  ctx.fillStyle = '#04204B';
  ctx.fillText(CAP[shown], width / 2, 24);
  ctx.globalAlpha = 1;
  var fm = 'D = Σ wᵢ xᵢ / Σ wᵢ,   wᵢ ∝ exp(-|x - xᵢ|² / (2σ²))';
  fit(ctx, fm, width - 20, 12);
  ctx.fillStyle = '#3D5F91';
  ctx.fillText(fm, width / 2, 44);

  // query on path
  var phi = 6.283185307 * time / PERIOD + 0.9;
  var qx = 0.5 + 1.2 * Math.cos(phi), qy = 0.25 + 0.6 * Math.sin(phi);

  // exact denoiser
  var dmin = 1e9, i, j;
  for (i = 0; i < N; i++) {
    var dx = qx - X[i], dy = qy - Y[i];
    D2[i] = dx * dx + dy * dy;
    if (D2[i] < dmin) dmin = D2[i];
  }
  var sw = 0, sx = 0, sy = 0, inv = 1 / (2 * sig * sig);
  for (i = 0; i < N; i++) {
    W[i] = Math.exp(-(D2[i] - dmin) * inv);
    sw += W[i]; sx += W[i] * X[i]; sy += W[i] * Y[i];
    SH[i] = (i % 15 === 0) ? 1 : 0;
  }
  var Dx = sx / sw, Dy = sy / sw;
  for (j = 0; j < 4; j++) {
    var bi = -1, bw = -1;
    for (i = 0; i < N; i++) { if (W[i] > bw && SH[i] !== 2) { bw = W[i]; bi = i; } }
    if (bi >= 0 && SH[bi] === 0) SH[bi] = 3;
    else if (bi >= 0 && SH[bi] === 1) SH[bi] = 3;
    if (bi >= 0) { W[bi] = W[bi]; SH[bi] = 3; }
    // mark as consumed via temp trick
    if (bi >= 0) { SH[bi] = 2 + 0; W[bi] = -W[bi]; }
  }
  for (i = 0; i < N; i++) { if (W[i] < 0) { W[i] = -W[i]; SH[i] = 1; } }

  var qpx = PX(qx), qpy = PY(qy), dpx = PX(Dx), dpy = PY(Dy);

  // clip to plot area
  ctx.save();
  ctx.beginPath(); ctx.rect(4, plotTop - 6, width - 8, ph + 12); ctx.clip();

  // query path guide
  ctx.strokeStyle = 'rgba(128,152,188,0.45)'; ctx.lineWidth = 1;
  ctx.setLineDash([3, 4]);
  ctx.beginPath(); ctx.ellipse(PX(0.5), PY(0.25), 1.2 * s, 0.6 * s, 0, 0, 6.2832); ctx.stroke();
  ctx.setLineDash([]);

  // sigma window
  ctx.fillStyle = 'rgba(11,79,192,0.05)';
  ctx.strokeStyle = 'rgba(11,79,192,0.35)';
  ctx.beginPath(); ctx.arc(qpx, qpy, sig * s, 0, 6.2832); ctx.fill(); ctx.stroke();

  // data
  ctx.fillStyle = 'rgba(128,152,188,0.5)';
  for (i = 0; i < N; i++) { ctx.beginPath(); ctx.arc(PX(X[i]), PY(Y[i]), 2, 0, 6.2832); ctx.fill(); }

  // weight lines
  ctx.lineWidth = 1.2;
  for (i = 0; i < N; i++) {
    if (SH[i] === 1 && W[i] > 0.02) {
      ctx.strokeStyle = 'rgba(180,85,47,' + (0.7 * W[i]).toFixed(3) + ')';
      ctx.beginPath(); ctx.moveTo(qpx, qpy); ctx.lineTo(PX(X[i]), PY(Y[i])); ctx.stroke();
    }
  }
  for (i = 0; i < N; i++) {
    if (W[i] > 0.04) {
      ctx.fillStyle = 'rgba(180,85,47,' + Math.min(0.9, W[i]).toFixed(3) + ')';
      ctx.beginPath(); ctx.arc(PX(X[i]), PY(Y[i]), 2.6, 0, 6.2832); ctx.fill();
    }
  }

  // arrow x -> D
  var ax = dpx - qpx, ay = dpy - qpy, L = Math.sqrt(ax * ax + ay * ay);
  if (L > 12) {
    var ux = ax / L, uy = ay / L;
    var x1 = qpx + ux * 7, y1 = qpy + uy * 7, x2 = dpx - ux * 7, y2 = dpy - uy * 7;
    ctx.strokeStyle = '#0B4FC0'; ctx.lineWidth = 2;
    ctx.beginPath(); ctx.moveTo(x1, y1); ctx.lineTo(x2, y2); ctx.stroke();
    ctx.fillStyle = '#0B4FC0';
    ctx.beginPath(); ctx.moveTo(x2 + ux * 3, y2 + uy * 3);
    ctx.lineTo(x2 - ux * 7 - uy * 4.5, y2 - uy * 7 + ux * 4.5);
    ctx.lineTo(x2 - ux * 7 + uy * 4.5, y2 - uy * 7 - ux * 4.5); ctx.closePath(); ctx.fill();
  }
  // D dot
  ctx.fillStyle = '#0B4FC0';
  ctx.beginPath(); ctx.arc(dpx, dpy, 5.5, 0, 6.2832); ctx.fill();
  // query
  ctx.fillStyle = '#ffffff'; ctx.strokeStyle = '#04204B'; ctx.lineWidth = 2;
  ctx.beginPath(); ctx.arc(qpx, qpy, 5.5, 0, 6.2832); ctx.fill(); ctx.stroke();
  ctx.restore();

  // labels
  label(ctx, 'x', qpx - 16, qpy - 10, width, '#04204B');
  label(ctx, 'D(x, σ)', dpx + 9, dpy + 18, width, '#0B4FC0');

  // sigma gauge
  var gy = height - 52, gx0 = 34, gx1 = width - 84;
  var lo = Math.log(0.04), hi = Math.log(3);
  function GX(v) { return gx0 + (gx1 - gx0) * (Math.log(v) - lo) / (hi - lo); }
  ctx.font = '13px sans-serif'; ctx.textAlign = 'left'; ctx.fillStyle = '#04204B';
  ctx.fillText('σ', 14, gy + 4);
  ctx.strokeStyle = '#8098BC'; ctx.lineWidth = 3; ctx.lineCap = 'round';
  ctx.beginPath(); ctx.moveTo(gx0, gy); ctx.lineTo(gx1, gy); ctx.stroke();
  ctx.lineCap = 'butt';
  var names = ['high', 'medium', 'low'];
  ctx.font = '11px sans-serif'; ctx.textAlign = 'center';
  for (i = 0; i < 3; i++) {
    var tx = GX(SIG[i]);
    ctx.strokeStyle = '#8098BC'; ctx.lineWidth = 1;
    ctx.beginPath(); ctx.moveTo(tx, gy - 6); ctx.lineTo(tx, gy + 6); ctx.stroke();
    ctx.fillStyle = (i === shown) ? '#04204B' : '#3D5F91';
    ctx.fillText(names[i], tx, gy + 20);
  }
  var mx = GX(sig);
  ctx.strokeStyle = '#0B4FC0'; ctx.lineWidth = 3; ctx.lineCap = 'round';
  ctx.beginPath(); ctx.moveTo(gx0, gy); ctx.lineTo(mx, gy); ctx.stroke(); ctx.lineCap = 'butt';
  ctx.fillStyle = '#0B4FC0';
  ctx.beginPath(); ctx.arc(mx, gy, 6.5, 0, 6.2832); ctx.fill();
  ctx.font = '13px sans-serif'; ctx.textAlign = 'left'; ctx.fillStyle = '#04204B';
  ctx.fillText('σ = ' + sig.toFixed(2), gx1 + 12, gy + 4);

  // legend
  ctx.font = '11px sans-serif'; ctx.textAlign = 'left';
  var items = ['query x', 'D(x, σ)', 'weight of xᵢ'];
  var tw = [], total = 0;
  for (i = 0; i < 3; i++) { tw.push(ctx.measureText(items[i]).width); total += tw[i] + 20 + (i < 2 ? 14 : 0); }
  var lx = Math.max(4, (width - total) / 2), ly = height - 12;
  for (i = 0; i < 3; i++) {
    var cx = lx + 6, cy = ly - 4;
    if (i === 0) { ctx.fillStyle = '#ffffff'; ctx.strokeStyle = '#04204B'; ctx.lineWidth = 2; ctx.beginPath(); ctx.arc(cx, cy, 4.5, 0, 6.2832); ctx.fill(); ctx.stroke(); }
    else if (i === 1) { ctx.fillStyle = '#0B4FC0'; ctx.beginPath(); ctx.arc(cx, cy, 4.5, 0, 6.2832); ctx.fill(); }
    else { ctx.strokeStyle = '#B4552F'; ctx.lineWidth = 2; ctx.beginPath(); ctx.moveTo(cx - 6, cy); ctx.lineTo(cx + 6, cy); ctx.stroke(); }
    ctx.fillStyle = '#3D5F91';
    ctx.fillText(items[i], lx + 18, ly);
    lx += tw[i] + 20 + 14;
  }
}
return { draw: draw };
